def _a_horario(apps, schema_editor):
    """La frecuencia anterior, traducida al horario nuevo.

    «Diaria» son los siete días; «semanal», solo el suyo. La hora pasa a ser la
    única de la lista. La marca del último respaldo automático se conserva como
    turno cubierto a esa hora, para que la primera pasada tras la migración no
    repita el de hoy.
    """
    import datetime

    from django.utils import timezone

    Politica = apps.get_model("core", "PoliticaDeRespaldo")
    for politica in Politica.objects.all():
        if politica.frecuencia == "semanal":
            politica.dias = [politica.dia_semanal]
        else:
            politica.dias = [0, 1, 2, 3, 4, 5, 6]
        politica.horas = [politica.hora.strftime("%H:%M")]
        if politica.ultimo_respaldo:
            politica.ultimo_programado = timezone.make_aware(
                datetime.datetime.combine(politica.ultimo_respaldo, politica.hora)
            )
        politica.save(update_fields=["dias", "horas", "ultimo_programado"])


